/* Fula Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Amina": "trustworthy — Arabic", "Musa": "The Fula form of Moses.", "Ibrahim": "The Fula form of Abraham.", "Fatima": "A beloved feminine name.", "Abdoulaye": "servant of God — Arabic Abdallah", "Mariama": "A popular feminine name.", "Diallo": "One of the four great Fulani clan names.", "Bah": "One of the four great Fulani clan names.", "Barry": "One of the four great Fulani clan names.", "Sow": "One of the four great Fulani clan names."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Amina';
console.log(lookup(q));

